package com.badrulamin.University_Management.service; import com.badrulamin.University_Management.exception.ResourceNotFoundException;  import com.badrulamin.University_Management.entity.ApplicationReview; import com.badrulamin.University_Management.repository.ApplicationReviewRepository; import org.springframework.data.domain.Page; import org.springframework.data.domain.Pageable; import org.springframework.stereotype.Service;  import java.time.LocalDateTime; import java.util.List;  @Service public class ApplicationReviewService {      private final ApplicationReviewRepository applicationReviewRepository;      public ApplicationReviewService(ApplicationReviewRepository applicationReviewRepository) {         this.applicationReviewRepository = applicationReviewRepository;     }      public Page<ApplicationReview> findAll(Pageable pageable) {         return applicationReviewRepository.findAll(pageable);     }      public ApplicationReview findById(Long id) {         return applicationReviewRepository.findById(id).orElseThrow(() -> new ResourceNotFoundException("ApplicationReview", "id", id));     }      public ApplicationReview create(ApplicationReview review) {         review.setReviewedAt(LocalDateTime.now());         return applicationReviewRepository.save(review);     }      public ApplicationReview update(Long id, ApplicationReview review) {         ApplicationReview existing = applicationReviewRepository.findById(id)                 .orElseThrow(() -> new ResourceNotFoundException("ApplicationReview", "id", id));         existing.setApplication(review.getApplication());         existing.setReviewer(review.getReviewer());         existing.setStatus(review.getStatus());         existing.setComments(review.getComments());         existing.setRejectionReason(review.getRejectionReason());         existing.setScore(review.getScore());         existing.setIsRecommended(review.getIsRecommended());         return applicationReviewRepository.save(existing);     }      public void delete(Long id) {         applicationReviewRepository.deleteById(id);     }      public long countByStatus(String status) {         return applicationReviewRepository.countByStatus(status);     } }